def min_flip_to_make_string_alternate(str):
    """Write a function to find the number of flips required to make the given binary string a sequence of alternate characters."""
    flips_start_zero = 0
    flips_start_one = 0
    for i, ch in enumerate(str):
        expected_zero = '0' if i % 2 == 0 else '1'
        expected_one = '1' if i % 2 == 0 else '0'
        if ch != expected_zero:
            flips_start_zero += 1
        if ch != expected_one:
            flips_start_one += 1
    return min(flips_start_zero, flips_start_one)
